require_once __DIR__.'/includes/auth.php';require_permission('settings');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fields=['barangay_name','municipality','province','official_address','contact_details','logo_url','punong_barangay','records_signatory','official_wording','payment_instructions'];foreach($fields as $field){$value=trim((string)($_POST[$field]??''));$pdo->prepare('INSERT INTO system_settings (`key`,`value`,updated_by) VALUES (?,?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`),updated_by=VALUES(updated_by)')->execute([$field,$value,current_user()['id']]);}audit_action('system_settings_updated','system_settings',null,'Barangay identity and official templates');flash('success','Barangay profile and official wording saved.');redirect('settings.php');}
$settings=[];foreach($pdo->query('SELECT `key`,`value` FROM system_settings')->fetchAll() as $row)$settings[$row['key']]=$row['value'];$pageTitle='Barangay settings';$activePage='settings';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Official identity</div><h1>Barangay settings</h1><p>Keep the official identity, signatories, wording, and payment instructions used by printed documents in one controlled place.</p></div></section><section class="panel form-panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Barangay name<input name="barangay_name" value="<?= h($settings['barangay_name']??'') ?>" placeholder="Barangay San Isidro" required></label><label>Municipality<input name="municipality" value="<?= h($settings['municipality']??'') ?>" required></label><label>Province<input name="province" value="<?= h($settings['province']??'') ?>" required></label><label>Official address<input name="official_address" value="<?= h($settings['official_address']??'') ?>"></label><label>Contact details<input name="contact_details" value="<?= h($settings['contact_details']??'') ?>" placeholder="Phone · email"></label><label>Logo/seal URL<input type="url" name="logo_url" value="<?= h($settings['logo_url']??'') ?>" placeholder="https://..."></label><label>Punong Barangay<input name="punong_barangay" value="<?= h($settings['punong_barangay']??'') ?>" required></label><label>Records signatory<input name="records_signatory" value="<?= h($settings['records_signatory']??'') ?>"></label><label class="wide">Official document wording<textarea name="official_wording" rows="4"><?= h($settings['official_wording']??'') ?></textarea></label><label class="wide">Official receipt/payment instructions<textarea name="payment_instructions" rows="3"><?= h($settings['payment_instructions']??'') ?></textarea></label><div class="form-actions"><button class="primary-button">Save official settings</button></div></form></section><?php require __DIR__.'/partials/footer.php'; ?>
